def find_closest_apple(image):
    image_patch = ImagePatch(image)
    apple_patches = image_patch.find("apple")
    if not apple_patches:
        return "No apples found"

    # Sort apples by their distance from the center of the image
    center_x, center_y = image.shape[1] // 2, image.shape[0] // 2
    apple_patches.sort(key=lambda patch: ((patch.left + patch.right) / 2 - center_x) ** 2 + ((patch.lower + patch.upper) / 2 - center_y) ** 2)

    closest_apple = apple_patches[0]
    return closest_apple.llm_query(f"What variety of apple is located at ({closest_apple.left}, {closest_apple.lower})?", long_answer=False)

